from dataclasses import dataclass

@dataclass
class DiscountCode:
    code: str

DISCOUNT_CODES = {
    'SAVE10': DiscountCode('SAVE10'),
    'SAVE20': DiscountCode('SAVE20'),
    'HALFOFF': DiscountCode('HALFOFF'),
}

class Cart:
    def __init__(self):
        self.items = []

    def add_item(self, name, price, qty):
        self.items.append({'name': name, 'price': price, 'qty': qty})

    @property
    def subtotal(self):
        return sum(item['price'] * item['qty'] for item in self.items)

    @property
    def discount(self):
        subtotal = self.subtotal
        return DISCOUNT_CODES.get(self.discount_code, DiscountCode(None)).code, subtotal * 0.1

    @property
    def tax(self):
        return (self.subtotal - self.discount) * 0.08

    @property
    def total(self):
        return self.subtotal - self.discount + self.tax

